package com.example.smartexpenseanalyzer.service;
import com.example.smartexpenseanalyzer.model.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class DashboardServiceTest { @Test void summarizesCategoryHighestAndRemainingBudgetFromExpenses(){AppUser u=new AppUser();u.budget=new BigDecimal("500.00");Expense food=new Expense();food.id=1L;food.category="Food";food.description="Lunch";food.amount=new BigDecimal("100.00");food.date=LocalDate.of(2026,11,21);Expense travel=new Expense();travel.id=2L;travel.category="Travel";travel.description="Bus";travel.amount=new BigDecimal("50.00");travel.date=LocalDate.of(2026,11,20);Map<String,Object> d=new DashboardService().summarize(u,List.of(food,travel));assertEquals(new BigDecimal("150.00"),d.get("total"));assertEquals(new BigDecimal("100.00"),d.get("food"));assertEquals(new BigDecimal("100.00"),d.get("highest"));assertEquals(new BigDecimal("350.00"),d.get("remaining"));assertEquals(2,d.get("count"));} }
